    import java.util.*;
    /** 


    A thread unsafe iterator over two lists to convert them 
    into a map such that keys in first list at a certain
    index map onto values in the second list  at the same index.



    Created by kmhaswade on 5/10/16.
    */
    public class DualIterator implements Iterable> {
    private final List keys;
    private final List values;
    private int anchor = 0;
    public DualIterator(List keys, List values) {
    // do all the validations here
    this.keys = keys;
    this.values = values;
    }
    @Override
    public Iterator> iterator() {
    return new Iterator>() {
    @Override
    public boolean hasNext() {
    return keys.size() > anchor;
    }
    @Override
    public Map.Entry next() {
    Map.Entry e = new AbstractMap.SimpleEntry<>(keys.get(anchor), values.get(anchor));
    anchor += 1;
    return e;
    }
    };
    }
