    tChar = t.charAt(tIndex);
    sCharIsDigit = Character.isDigit(sChar);
    tCharIsDigit = Character.isDigit(tChar);
    if (!sCharIsDigit && !tCharIsDigit) {
    // both number sub words have the same length
    if (diff != 0) {
    return diff;
    }
    break;
    }
    if (!sCharIsDigit) {
    return -1;
    }
    if (!tCharIsDigit) {
    return 1;
    }
    } while (true);
