     public static Map fromArray(Object[] anObjArray){
    int size = anObjArray.length;
    Map aMap = new HashMap();
    for (int i=0;i<=size/2;i=i+2){
    K key = (K)anObjArray[i];
    V value = (V)anObjArray[i+1];
    aMap.put(key, value);
