     //alt. 1
    List offers;
    List cars;
    Map> mapCarToOffers;
    Map> mapOfferToCars;
    public void List getOffersForCar(Car aCar);
    public void List getCarsForOffer(Offer anOffer);


Alternative 1 would make use of the `hashCode()` of `Car` and `Offer`


     //alt. 2
    List offers;
    List cars;
    Map> mapCarIdToOffers;
    Map> mapOfferIdToCars;
