String -> Collection conversion: (String -> String[] -> Collection)


    // java version 8
    String str = "aa,bb,cc,dd,aa,ss,bb,ee,aa,zz,dd,ff,hh";
    // Collection,
    // Set , List,
    // HashSet , ArrayList ...
    // (____________________________)
