    if(panelArray.get(i).tempStart <= timeStart && panelArray.get(i).tempEnd >= timeEnd ) {
    //Do Nothing
    }
    else 
    {
    temps.dev = devIDStr;
    temps.inst = instanceStr;
    temps.tempStart = timeStart;
    temps.tempEnd = timeEnd;
    insert();
    panelArray.set(i, temps);
    }
    }
    else
    {
    temps.dev = devIDStr;
    temps.inst = instanceStr;
    temps.tempStart = timeStart;
    temps.tempEnd = timeEnd;
    panelArray.add(temps);
    insert();
    }
    }
    }


