MultiKeyMap get method 

I want to use MultiKeyMap from Apache Collection, because I need a HashMap with two keys and a value. To put elements I do this:


    private MultiKeyMap multiKey = new MultiKeyMap();
    multiKey.put("key1.1", "key2.1", "value1");


And for get element I do this:


    String s = multiKey.get("key1.1");


But the String s cames null... If I pass the two keys, like that:


    String s = multiKey.get("key1.1", "key2.1");


The String s cames with values value1...

How can I extend the MultiKeyMap to get the right value when I pass only one of the two keys?

Here is a simple MultiKeyMap implementation that worked for me.


    import java.util.Collection;
    import java.util.HashMap;
    import java.util.HashSet;
    import java.util.Map;
    import java.util.Set;
    import java.util.UUID;
    public class MultiMap implements Map
    {
    private class MultiMapEntery implements java.util.Map.Entry
    {
    private final K key;
    private V value;
    public MultiMapEntery(K key, V value)
    {
    this.key = key;
    this.value = value;
    }
    @Override
    public K getKey()
    {
    return key;
    }
    @Override
    public V getValue()
    {
    return value;
    }
    @Override
    public V setValue(V value)
    {
    V oldValue = this.value;
    this.value = value;
    return oldValue;
    }
    };
    private final Map keyMap = new HashMap();
    private final Map> inverseKeyMap = new HashMap>();
    private final Map valueMap = new HashMap();
    @Override
    public void clear()
    {
    keyMap.clear();
    inverseKeyMap.clear();
    valueMap.clear();
    }
    @Override
    public boolean containsKey(Object key)
    {
    return keyMap.containsKey(key);
    }
    @Override
    public boolean containsValue(Object value)
    {
    return valueMap.containsValue(value);
    }
    @Override
    public Set> entrySet()
    {
    Set> entries = new HashSet<>();
    for(K key : keyMap.keySet())
    {
    V value = valueMap.get(key);
    entries.add(new MultiMapEntery(key, value));
    }
    return entries;
    }
    @Override
    public V get(Object key)
    {
    return valueMap.get(keyMap.get(key));
    }
    @Override
    public boolean isEmpty()
    {
    return valueMap.isEmpty();
    }
    @Override
    public Set keySet()
    {
    return keyMap.keySet();
    }
    @Override
    public V put(K key, V value)
    {
    String id = keyMap.get(key);
    if(id == null)
    {
    id = UUID.randomUUID().toString();
    }
    keyMap.put(key, id);
    Set keys = inverseKeyMap.get(id);
    if(keys == null)
    {
    keys = new HashSet<>();
    }
    keys.add(key);
    inverseKeyMap.put(id, keys);
    valueMap.put(id, value);
    return value;
    }
    public V put(Set keys, V value)
    {
    String id = null;
    for(K key : keys)
    {
    id = keyMap.get(key);
    if(id != null) // one of the keys already exists
    {
    break;
    }
    }
    if(id == null)
    {
    id = UUID.randomUUID().toString();
    }
    for(K key : keys)
    {
    keyMap.put(key, id);
    }
    inverseKeyMap.put(id, keys);
    valueMap.put(id, value);
    return value;
    }
    @Override
    public void putAll(Map map)
    {
    for(java.util.Map.Entry entry : map.entrySet())
    {
    put(entry.getKey(), entry.getValue());
    }
    }
    @Override
    public V remove(Object key)
    {
    String id = keyMap.get(key);
    keyMap.remove(key);
    Set keys = inverseKeyMap.get(id);
    keys.remove(key);
    V value = valueMap.get(id);
    if(keys.size() == 0) // it was the last key, now remove the value
    {
    valueMap.remove(id);
    }
    return value;
    }
    @Override
    public int size()
    {
    return valueMap.size();
    }
    @Override
    public Collection values()
    {
    return valueMap.values();
    }
    public static void main(String[] args)
    {
    MultiMap m = new MultiMap<>();
    m.put("a", "v1");
    Set s = new HashSet<>();
    s.add("b");
    s.add("c");
    s.add("d");
    m.put(s, "v2");
    System.out.println("size:" + m.size());
    System.out.println("keys:" + m.keySet());
    System.out.println("values:" + m.values().toString());
    System.out.println("a:" + m.get("a"));
    System.out.println("b:" + m.get("b"));
    System.out.println("c:" + m.get("c"));
    System.out.println("d:" + m.get("d"));
    m.remove("a");
    System.out.println("size:" + m.size());
    System.out.println("keys:" + m.keySet());
    System.out.println("values:" + m.values().toString());
    System.out.println("a:" + m.get("a"));
    System.out.println("b:" + m.get("b"));
    System.out.println("c:" + m.get("c"));
    System.out.println("d:" + m.get("d"));
    s.add("a");
    m.put(s, "v3");
    System.out.println("size:" + m.size());
    System.out.println("keys:" + m.keySet());
    System.out.println("values:" + m.values().toString());
    System.out.println("a:" + m.get("a"));
    System.out.println("b:" + m.get("b"));
    System.out.println("c:" + m.get("c"));
    System.out.println("d:" + m.get("d"));
    }
    }

