     /**
    * @param args
    * @throws FileNotFoundException
    */
    private static int totalLineCount = 0;
    private static int totalFileScannedCount = 0;
    public static void main(final String[] args) throws Exception {
    JFileChooser chooser = new JFileChooser();
    chooser.setCurrentDirectory(new java.io.File("C:" + File.separator));
    chooser.setDialogTitle("FILES ALONG WITH LINE NUMBERS");
    chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
    chooser.setAcceptAllFileFilterUsed(false);
    if (chooser.showOpenDialog(null) == JFileChooser.APPROVE_OPTION) {
    Map result = new HashMap();
    File directory = new File(chooser.getSelectedFile().getAbsolutePath());
    List files = getFileListing(directory);
    // print out all file names, in the the order of File.compareTo()
    for (File file : files) {
    // System.out.println("Directory: " + file);
    getFileLineCount(result, file);
    //totalFileScannedCount += result.size(); //saral
    }
    System.out.println("*****************************************");
    System.out.println("FILE NAME FOLLOWED BY LOC");
    System.out.println("*****************************************");
    for (Map.Entry entry : result.entrySet()) {
    System.out.println(entry.getKey().getAbsolutePath() + " ==> " + entry.getValue());
    }
    System.out.println("*****************************************");
    System.out.println("SUM OF FILES SCANNED ==>" + "\\t" + totalFileScannedCount);
    System.out.println("SUM OF ALL THE LINES ==>" + "\\t" + totalLineCount);
    }
    }
    public static void getFileLineCount(final Map result, final File directory)
    throws FileNotFoundException {
    File[] files = directory.listFiles(new FilenameFilter() {
    public boolean accept(final File directory, final String name) {
    if (name.endsWith(".java")) {
    return true;
    } else {
    return false;
    }
    }
    });
    for (File file : files) {
    if (file.isFile()) {
    Scanner scanner = new Scanner(new FileReader(file));
    int lineCount = 0;
    totalFileScannedCount ++; //saral
    try {
    /*for (lineCount = 0; scanner.nextLine() != null;lineCount++ ) { //saral
    ;
    }*/
    while (scanner.hasNextLine()) {
    String line = scanner.nextLine().trim();
    if (!line.isEmpty()) {
    System.out.println("debug-->"+line); // to debug cross checked that no whitespaces are there 
    lineCount++;
    }
    }
    result.put(file, lineCount);
    totalLineCount += lineCount; 
    } catch (NoSuchElementException e) {
    e.printStackTrace();
    }
    }
    }
    }
    /**
    * Recursively walk a directory tree and return a List of all Files found;
    * the List is sorted using File.compareTo().
    * 
    * @param aStartingDir
    * is a valid directory, which can be read.
    */
    static public List getFileListing(final File aStartingDir) throws FileNotFoundException {
    validateDirectory(aStartingDir);
    List result = getFileListingNoSort(aStartingDir);
    Collections.sort(result);
    return result;
    }
    // PRIVATE //
    static private List getFileListingNoSort(final File aStartingDir) throws FileNotFoundException {
    List result = new ArrayList();
    File[] filesAndDirs = aStartingDir.listFiles();
    List filesDirs = Arrays.asList(filesAndDirs);
    for (File file : filesDirs) {
    if (file.isDirectory()) {
    result.add(file);
    }
    if (!file.isFile()) {
    // must be a directory
    // recursive call!
    List deeperList = getFileListingNoSort(file);
    result.addAll(deeperList);
    }
    }
    return result;
    }
    /**
    * Directory is valid if it exists, does not represent a file, and can be
    * read.
    */
    static private void validateDirectory(final File aDirectory) throws FileNotFoundException {
    if (aDirectory == null) {
    throw new IllegalArgumentException("Directory should not be null.");
    }
    if (!aDirectory.exists()) {
    throw new FileNotFoundException("Directory does not exist: " + aDirectory);
    }
    if (!aDirectory.isDirectory()) {
    throw new IllegalArgumentException("Is not a directory: " + aDirectory);
    }
    if (!aDirectory.canRead()) {
    throw new IllegalArgumentException("Directory cannot be read: " + aDirectory);
    }
    }


