    public String toHtmlTable(Collection values, int columns) {
    StringBuilder sb = new StringBuilder();
    if(values != null && ! values.isEmpty() && columns > 0) {
    sb.append("");
    List valuesList = new ArrayList(values);
    int numberOfitemsInOneColumn = (valuesList.size() / columns) + (valuesList.size() % columns != 0 ? 1 : 0);
    String arr[][] = new String[columns][numberOfitemsInOneColumn];
    int i = 0;
    int s = valuesList.size();
    for(int x = 0; x < columns && i < s; x++) {
    for(int y = 0; y < numberOfitemsInOneColumn; y++) {
    if(i < s) {
    arr[x][y] = valuesList.get(i++);
    } else {
    break;
    }
    }
    }
    for(int y = 0; y < numberOfitemsInOneColumn; y++) {
    sb.append("\\n \\n");
    for(int x = 0; x < columns; x++) {
    if(x == 0) {
    sb.append(" ");
    }
    sb.append("");
    if(arr[x][y] != null) {
    sb.append(arr[x][y]);
    }
    sb.append("");
    if(x == columns) {
    sb.append("\\n");
    }
    }
    sb.append("\\n   
    ---  
    ");
    }
    sb.append("\\n\\n");
    }
    return sb.toString();
    }
    private void printList(Collection data) {
    for(String s : data) {
    print(s);
    print(" ");
    }
    print("\\n");
    }
    private void print(String s) {
    if(s != null) {
    System.out.print(s);
    }
    }
    }


here is another version using one loop only


    public String toHtmlTableSingleLoop(Collection values, int columns) {
    StringBuilder sb = new StringBuilder();
    if(values != null && ! values.isEmpty() && columns > 0) {
    List valuesList = new ArrayList(values);
    int numberOfitemsInOneColumn = (valuesList.size() / columns) + 
    (valuesList.size() % columns != 0 ? 1 : 0);
    int j = 0, columnCounter = 0, rowColumnCounter = 0;
    sb.append("");
    for(int i = 0; i < valuesList.size(); i++) {
    if(i % columns == 0) {
    rowColumnCounter = columnCounter++;
    j = rowColumnCounter;
    sb.append("  
    ---  
    \\n");
    } else {
    j += numberOfitemsInOneColumn;
    }
    if(j < valuesList.size()) {
    sb.append("" + valuesList.get(j) + "");
    }
    rowColumnCounter++;
    }
    sb.append("\\n  
    \\n");
    }
    return sb.toString();
    }

