    if (xAxis == null) {
    if (other.xAxis != null) {
    return false;
    }
    } else if (!xAxis.equals(other.xAxis)) {
    return false;
    } else if (!xAxis.toString().equals(other.xAxis.toString())) {
    return false;
    }
    ...


