    public class ListMap implements Iterator
    {
    private final Map> _map;
    private Iterator>> _it1 = null;
    private Iterator _it2 = null;
    public ListMap(Map> map)
    {
    _map = map;
    _it1 = map.entrySet().iterator(); 
    nextList();
    }
