    lists.add(Arrays.asList("A", "B", "4"));
    lists.add(Arrays.asList("A", "B", "1"));
    lists.add(Arrays.asList("A", "B", "3"));
    lists.add(Arrays.asList("A", "B", "2"));
    lists.add(Arrays.asList("A", "A", "9"));
    lists.add(Arrays.asList("A", "C", "0"));
    Comparator c = comparableComparator();
    Comparator> cc = createCompatator(c);
    Collections.sort(lists, cc);
    for (List list : lists)
    {
    System.out.println(list);
    }
    }
    private static > Comparator comparableComparator()
    {
    return new Comparator()
    {
    @Override
    public int compare(T t0, T t1)
    {
    return t0.compareTo(t1);
    }
    };
    }
    public static  Comparator> createCompatator(
    final Comparator comparator)
    {
    return new Comparator>()
    {
    @Override
    public int compare(List list0, List list1)
    {
    int n = Math.min(list0.size(), list1.size());
    for (int i=0; i

A colexicographical comparator can be implemented by reversing the list traversal direction.

The comparator in this example could also be generalized to a `Comparator>`, by using manual traversal with two `Iterator` instances obtained from the collections.

