Thank you This solution is faster than TreeSet because use HashSet rather than TreeSet and it solve your problem completely. here will be your student class :


    public class Student {
    private String name;
    private int grade;
    public Student(String name, int grade) {
    this.name = name;
    this.grade = grade;
    }
    public String getName() {
    return name;
    }
    public int getGrade() {
    return grade;
    }
    public void setName(String name) {
    this.name = name;
    }
    public void setGrade(int grade) {
    this.grade = grade;
    }
    @Override
    public int hashCode() {
    return name.hashCode();
    }
    @Override
    public boolean equals(Object obj) {
    Student external = (Student) obj;
    if (external.getGrade() > this.getGrade()) {
    external.setGrade(this.getGrade());
    return true;
    } else {
    return true;
    }
    }
    }


