    list.add(new StringPair("K1", "V1")); 
    Collections.sort(list, new Comparator() 
    @Override
    public int compare(StringPair o1, StringPair o2) {
    return o1.value.compareTo(o2.value);
    } 
    });
    System.out.println(list); // Prints [[K1, V1], [K2, V2]]

