Group the map values to avoid duplicate I have a Map(map1) whose key is another map(map2) and value is string. The value of map1 has several duplicate, so I must group them and set as key in another map3 whose value has to be map2.


    eg:
    map1 { [[a,b],xyz], [[c,d],wrt] , [[e,f],xyz] , [[r,m],xyz] }
    output should be :
    map3 { [ xyz,[ [a,b],[e,f],[r,m] ] ] , [ wrt,[ [c,d] ]


can i obtain like this ? It is not clear from your post what do you mean by `map2`, but let's assume you would like to use each `Map.Entry entry` from `map2` for each key for `map1`. The following code is Java 7, it's a bit verbose. It could be done shorter with Java 8 streams, I guess.


    public class MapReverser {
    private Map, String> map1 = new HashMap<>();
    private Map map2 = new LinkedHashMap<>();
    private void prepareMaps() {
    map2.put("a", "b");
    map2.put("c", "d");
    map2.put("e", "f");
    map2.put("r", "m");
    String[] valueArray = { "xyz", "wrt", "xyz", "xyz" };
    int i = 0;
    for (Map.Entry entry : map2.entrySet()) {
    map1.put(entry, valueArray[i]);
    i++;
    }
    }
    public Map>> reverse() {
    Map>> reversedMap = new HashMap<>();
    for (Map.Entry, String> entry : map1.entrySet()) {
    List> reversedMapValue = reversedMap.get(entry.getValue());
    if (reversedMapValue == null) {
    reversedMapValue = new ArrayList<>();
    }
    reversedMapValue.add(entry.getKey());
    reversedMap.put(entry.getValue(), reversedMapValue);
    }
    return reversedMap;
    }
    private void printResult(Map>> reversedMap) {
    for (Map.Entry>> entry : reversedMap.entrySet()) {
    System.out.println("Key: \\n" + entry.getKey());
    System.out.println("Values:");
    List> valuesList = entry.getValue();
    for (Map.Entry value : valuesList) {
    System.out.println(value );
    }
    System.out.println("\\n");
    }
    }
    public static void main(String[] args) {
    MapReverser mapReverser = new MapReverser();
    mapReverser.prepareMaps();
    Map>> reversedMap = mapReverser.reverse();
    mapReverser.printResult(reversedMap);
    }
    }

